-- Jeu de LecteurChangementJuge (« Changer le juge-commissaire », PROC_CHM), lot 4 du plan « RIG v3 100 % fonctionnel »
-- (plan-676a4b19). Identifiants 14xx xxx. Tables aux types de RIG_DEV (INFORMATION_SCHEMA.COLUMNS de SQL-DEV\DEV, lu le
-- 26/11/2026), creees si absentes, completees sinon ; lignes par sp_executesql (les colonnes ajoutees dans le meme lot).
-- Ce jeu pose aussi les PC du lot 4, que lisent « Changer les organes » (PROC_CHORGANESENMASSE.sql), « Débiteurs multiples »
-- (PROC_DEBITEURS_MULTIPLES.sql) et « Liens entre PC » (PROC_XLIEN.sql). Numeros 1990P14xxx : ils se rangent apres les PC des
-- autres jeux dans la liste de PROC_MPC (numero decroissant), qui les montre toutes (PROC_MPC.attendu, PROC_MPC.gestes).
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NUM_PC') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NUM_PC varchar(10) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NOM_AFFAIRE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NOM_AFFAIRE varchar(max) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_FORFAIT_FACTURE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_FORFAIT_FACTURE bit NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_EXTERIEUR') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_EXTERIEUR bit NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_ID_CLIEN') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_ID_CLIEN int NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_SOLUTION') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_SOLUTION datetime NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_TYPE_PC') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_TYPE_PC varchar(5) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_OUVERTURE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_OUVERTURE datetime NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NOM_DEBITEUR_PRINCIPAL') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NOM_DEBITEUR_PRINCIPAL varchar(250) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_ID_ADRBS') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_ID_ADRBS int NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_INSCRIT_REGISTRE_METIER') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_INSCRIT_REGISTRE_METIER bit NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NUM_RM') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NUM_RM varchar(10) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DEPARTEMENT_RM') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DEPARTEMENT_RM varchar(3) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_RM_DEPENDANT') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_RM_DEPENDANT varchar(10) NULL;
IF OBJECT_ID(N'v2.PREVENTION') IS NULL
    CREATE TABLE v2.PREVENTION (PREVE_ID_PREVE int NOT NULL PRIMARY KEY, PREVE_NUM_PRV varchar(10) NULL, PREVE_NOM_AFFAIRE varchar(250) NULL);
IF COL_LENGTH('v2.PREVENTION', 'PREVE_TYPE_PRV') IS NULL ALTER TABLE v2.PREVENTION ADD PREVE_TYPE_PRV varchar(5) NULL;
IF COL_LENGTH('v2.PREVENTION', 'PREVE_DATE_OUVERTURE') IS NULL ALTER TABLE v2.PREVENTION ADD PREVE_DATE_OUVERTURE datetime NULL;
IF COL_LENGTH('v2.PREVENTION', 'PREVE_DATE_CLOTURE') IS NULL ALTER TABLE v2.PREVENTION ADD PREVE_DATE_CLOTURE datetime NULL;
IF OBJECT_ID(N'v2.JUGE') IS NULL
    CREATE TABLE v2.JUGE (JUG_ID_JUG int NOT NULL PRIMARY KEY, JUG_ABREGE varchar(16) NULL, JUG_CIVILITE varchar(7) NOT NULL,
        JUG_NOM varchar(35) NOT NULL, JUG_PRENOM varchar(20) NULL);
IF OBJECT_ID(N'v2.ETRE_JUGE_COMM') IS NULL
    CREATE TABLE v2.ETRE_JUGE_COMM (ETJCM_ID_ETJCM int NOT NULL PRIMARY KEY, ETJCM_ID_JUG int NOT NULL, ETJCM_ID_PRCLL int NULL,
        ETJCM_FONCTION_PC varchar(5) NOT NULL, ETJCM_FIN_MISSION bit NOT NULL, ETJCM_ID_PREVE int NULL, ETJCM_NUM_ORDRE smallint NULL);
IF OBJECT_ID(N'v2.ETRE_JUGE_COMM_EN_ATTENTE') IS NULL
    CREATE TABLE v2.ETRE_JUGE_COMM_EN_ATTENTE (ETJCMA_ID_ETJCMA int NOT NULL PRIMARY KEY, ETJCMA_ID_DCJDC int NOT NULL, ETJCMA_ID_PRCLL int NOT NULL,
        ETJCMA_ID_JUG_A_REMPLACER int NOT NULL, ETJCMA_ID_JUG_NOUVEAU int NOT NULL, ETJCMA_TYPE_CHANGEMENT_JUGE varchar(16) NOT NULL,
        ETJCMA_DATE_CREATION datetime NOT NULL, ETJCMA_AUTEUR_CREATION varchar(128) NOT NULL, ETJCMA_DATE_ORDOSIGN datetime NULL,
        ETJCMA_AUTEUR_ORDOSIGN varchar(128) NULL);
IF OBJECT_ID(N'v2.MANDATAIRE_PC') IS NULL
    CREATE TABLE v2.MANDATAIRE_PC (MNDPC_ID_MNDPC int NOT NULL PRIMARY KEY, MNDPC_CIVILITE varchar(7) NOT NULL, MNDPC_NOM varchar(100) NOT NULL,
        MNDPC_COMPLEMENT_NOM varchar(100) NULL);
IF OBJECT_ID(N'v2.GERER_PC') IS NULL
    CREATE TABLE v2.GERER_PC (GRRPC_ID_GRRPC int NOT NULL PRIMARY KEY, GRRPC_ID_MNDPC int NOT NULL, GRRPC_ID_PRCLL int NULL,
        GRRPC_NUM_ORDRE smallint NOT NULL, GRRPC_FONCTION_PC varchar(5) NOT NULL, GRRPC_FIN_MISSION bit NOT NULL, GRRPC_ID_PREVE int NULL);
IF OBJECT_ID(N'v2.CODE_SOLUTION') IS NULL
    CREATE TABLE v2.CODE_SOLUTION (R_CODESOLUTI_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_CODESOLUTI_SURVEILLANCE_RCS bit NOT NULL);
IF COL_LENGTH('v2.CODE_SOLUTION', 'R_CODESOLUTI_LIBELLE_ECRAN') IS NULL ALTER TABLE v2.CODE_SOLUTION ADD R_CODESOLUTI_LIBELLE_ECRAN varchar(35) NULL;

